draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // many truths coexisting
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 2) * 50, 20, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 2) * 50);
    ctx.lineTo(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 2) * 50 - 30);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 2) * 50 - 30);
    ctx.lineTo(W / 2 + Math.sin(t + i) * 100 - 20, H / 2 + Math.cos(t + i * 2) * 50 - 60);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 2) * 50 - 30);
    ctx.lineTo(W / 2 + Math.sin(t + i) * 100 + 20, H / 2 + Math.cos(t + i * 2) * 50 - 60);
    ctx.stroke();
  }

  ctx.restore();
}
